    function formatDateDMY(dateStr) {
        if (!dateStr) return '-';
        const date = new Date(dateStr);
        if (isNaN(date.getTime())) return '-';
        const day = String(date.getDate()).padStart(2, '0');
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const year = date.getFullYear();
        return `${day}/${month}/${year}`;
    }

    function generateQR(url, size = 90) {
        // Construir la URL con la cédula del usuario como parámetro
        const qrUrl = `${url}?cedula=${encodeURIComponent(userData.cedula || '')}`;

        // Devolver el div con un ID único para el QR (se generará después)
        return `<div id="qrcode-preview" style="width:${size}px;height:${size}px;margin:10px auto 0 auto;background:transparent;"></div>`;
    }

    // Nueva utilidad: asegura que la librería QR esté cargada
    function ensureQRCodeLibraryLoaded(callback) {
        if (window.QRCode) {
            callback();
            return;
        }
        const existing = document.querySelector('script[src*="qrcode.min.js"]');
        if (existing) {
            existing.addEventListener('load', callback);
            return;
        }
        const script = document.createElement('script');
        script.src = "https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js";
        script.onload = callback;
        document.head.appendChild(script);
    }

    // bandera para controlar precarga de fondos
    let backgroundsReady = false;

    // Precargar fondos (si están definidos) antes de habilitar descarga
    function preloadBackgrounds(frontBase64, backBase64, cb) {
        const toLoad = [];
        if (frontBase64) toLoad.push(frontBase64);
        if (backBase64) toLoad.push(backBase64);
        if (toLoad.length === 0) {
            backgroundsReady = true;
            if (cb) cb();
            return;
        }
        let loaded = 0;
        toLoad.forEach(src => {
            const img = new Image();
            img.onload = img.onerror = function() {
                loaded++;
                if (loaded === toLoad.length) {
                    backgroundsReady = true;
                    if (cb) cb();
                }
            };
            img.src = src;
        });
    }

    // Espera hasta que las imágenes, fondos (precargados) y (si aplica) el canvas del QR estén listas
    function waitForElementsReady(type, callback) {
        const previewContent = document.getElementById('preview-content');
        const check = () => {
            const imgs = previewContent.querySelectorAll('img');
            let allLoaded = true;
            imgs.forEach(img => {
                if (!img.complete || (img.naturalWidth === 0 && img.src)) allLoaded = false;
            });

            let qrReady = true;
            if (type === 'card') {
                const qrDiv = document.getElementById('qrcode-preview');
                if (!qrDiv) qrReady = false;
                else {
                    qrReady = !!(qrDiv.querySelector('canvas') || qrDiv.querySelector('img'));
                }
            }

            if (allLoaded && qrReady && backgroundsReady) {
                callback();
            } else {
                setTimeout(check, 250);
            }
        };
        check();
    }

